        "translation": "孫子說：戰爭是國家的重大事務，是關係軍民生死的處境，也是決定國家存亡的途徑，不能不審慎考察。",
        "analysis": "【主旨】全書以慎戰開篇：戰爭牽動人的生命與國家存亡，所以決策前必須全面考察，而不是崇尚輕率用兵。\\n【詞義】「兵」在此指戰爭及用兵之事；「地」不是單指地形，而是所處境域；「道」指通往存亡結果的途徑與規律；「察」含詳審、明辨。\\n【章法】三個判斷由「國之大事」推到「死生」「存亡」，層層加重，再以雙重否定「不可不察」收束，奠定全書理性籌算的基調。\\n【思想】本句不是鼓吹戰爭，而是要求掌權者正視戰爭成本；其中「民之生死」雖未展開，已構成後文計算國力、民力與久戰危害的倫理前提。"
