        "analysis": "【主旨】大軍出動以前，必須先看見戰車、兵員、遠程糧運、外交接待、器材維修等龐大成本。\\n【詞義】「馳車」是快速戰車，「革車」多指載運輜重或防護車；「帶甲」指披甲士卒；「內外之費」涵蓋前後方支出；「車甲之奉」是車輛甲兵的供應維護。數字具有典型大軍的估算意味，不必視為每戰固定編制。\\n【章法】長串物資清單與數量排比，最後才說「師舉」，刻意表明軍隊不是一聲令下便能無成本出動。\\n【思想】〈作戰〉主要談戰爭經濟與後勤，而非交戰技巧；它把慎戰原則具體化為每日耗費與社會動員。"
