      "readingAid": {
        "translation": "軍隊作戰若久拖不決，就會使兵器鈍損、士氣挫傷；攻城會使兵力耗盡；軍隊長期在外，國家財用便會不足。兵器鈍損、士氣受挫、力量耗盡、財貨枯竭，其他諸侯就會乘虛而起，即使有智者也難以收拾後果。因此，用兵只聽說過寧可方法稍笨而求速勝，沒見過為追求巧妙而長期作戰。戰爭持久而有利於國家的，從來沒有過。",
        "analysis": "【主旨】戰爭拖延會依次損耗兵器、士氣、兵力與國家財政，並招致第三方乘虛而入，所以應求可行的速勝。\\n【文本】「其用戰也，勝久則」一帶各本句讀、文字有差異，通行解多依上下文讀成戰事久延則鈍兵挫銳；原文尚待版本校定。\\n【詞義】「鈍兵」是兵器或軍勢疲鈍；「挫銳」是銳氣受挫；「暴師」是軍隊長期暴露、駐留在外；「拙速」不是草率冒進，而是在可勝前提下寧取不完美的迅速方案。\\n【思想】本段反對的是無法產生決定結果的消耗戰，不能曲解為所有戰事越快越好；倉促行動若缺乏〈始計〉的評估，同樣違反慎戰。"
      }
