      "readingAid": {
        "translation": "將領是國君的輔佐。輔佐周密，國家必強；輔佐有缺失，國家必弱。國君危害軍隊的情形有三種：不知道軍隊不能前進卻命令前進，不知道不能後退卻命令後退，這叫束縛軍隊；不懂軍中事務卻幹預軍政，使士卒迷惑；不懂軍事權變卻幹預指揮，使士卒疑慮。軍隊既迷惑又疑慮，諸侯便會乘隙進犯；這叫擾亂自己的軍隊而送掉勝利。",
        "analysis": "【主旨】將領是國家軍事能力的重要支柱；君主若不了解前線條件卻直接幹預進退、軍政與權變，會使軍隊迷惑而把勝機讓給敵人。\\n【詞義】「輔周」是輔佐完密，「輔隙」是有缺漏；「縻軍」是束縛軍隊；兩個「同」有參預、干涉之意；「權」是臨機處置；「亂軍引勝」是自亂其軍而把勝利引向敵方。\\n【章法】三患依序從錯誤命令、幹預行政到幹預專業指揮，結果由惑、疑推至外敵乘隙。\\n【界限】這不是主張軍權不受文人政府監督，而是區分戰略目標、合法監督與即時專業指揮；現代制度仍須有清楚授權、問責和文官統制。"
      }
