      "readingAid": {
        "translation": "如果預先知道交戰地點和日期，即使遠行千里也能會戰；若不知道地點與日期，左軍不能救右軍，右軍不能救左軍，前軍不能救後軍，後軍不能救前軍，何況遠隔幾十里，即使相隔數裏也難以及時救援。依我判斷，越國兵雖多，對取勝又有什麼幫助？所以說，勝利可以主動創造；敵軍雖多，也能使他無法集中交戰。",
        "analysis": "【主旨】知道決戰時間和地點，才能讓分散部隊按時集中；使敵不知，便可令其數量雖多卻不能共同作戰。\\n【詞義】「會戰」是如期會合交戰；「越人」指吳國所面對的越軍，帶有文本所處戰爭背景；「奚益於勝」是對勝利有何幫助；「勝可為」承上篇「勝不可為」而有條件地說：不能強迫敵人犯錯，卻可用示形與調動塑造局部勝勢；「無鬥」是不能集中形成有效戰鬥。\\n【章法】先正反比較知與不知戰期戰地，再以越軍為例，最後推出可塑造勝勢。\\n【思想】兩篇並不矛盾：「不可為」限制主觀強求，「可為」強調可藉情報、機動與分散敵軍創造條件。"
      }
