      "chapterId": "art-of-war_ch-6",
      "order": 6,
      "canonicalText": "故策之而知得失之計，作之而知動靜之理，形之而知死生之地，角之而知有餘不足之處。故形兵之極，至於無形；無形，則深間不能窺，智者不能謀。因形而措勝於眾，眾不能知，人皆知我所以勝之形，而莫知吾所以制勝之形；故其戰勝不復，而應形於無窮。",
