      "readingAid": {
        "translation": "古代兵法《軍政》說：「在戰場上用語言指揮互相聽不見，所以要使用鑼鼓；用動作指揮互相看不見，所以要使用旌旗。」鑼鼓和旌旗，是用來統一全軍將士的耳朵和眼睛的。軍隊的行動既然已經統一，那麼勇敢的士兵就不能單獨前進，怯懦的士兵也不能單獨後退，這就是指揮大部隊作戰的方法。因此，夜間作戰要多用火光和擊鼓，白天作戰要多用旌旗，這都是為了適應並改變士兵的聽覺與視覺，從而統一指揮。",
        "analysis": "【主旨】大部隊在噪音、距離與視線受限的戰場上，必須以統一的聽覺、視覺信號協同行動，避免個人擅進擅退。\\n【詞義】《軍政》是今已佚的古兵書；「金鼓」泛指鉦、鼓等聲號，「旌旗」是視覺信號；「一人之耳目」不是隻服務一人，而是使眾人視聽一致；「專一」是行動集中統一；「變人之耳目」是隨晝夜條件調整信息媒介。\\n【章法】先引權威說明信號由來，再推導紀律效果，最後分夜戰與晝戰。\\n【思想】本段本質是指揮通信：共同協議的信號降低協調成本。但統一行動不等於取消回報與判斷，可靠系統仍需處理誤傳、失聯和情勢變化。"
      }
