      "order": 1,
      "canonicalText": "孫子曰：凡用兵之法，將受命於君，合軍聚眾；圮地無舍，衢地合交，絕地無留，圍地則謀，死地則戰，途有所不由，軍有所不擊，城有所不攻，地有所不爭，君命有所不受。故將通於九變之利者，知用兵矣。將不通於九變之利者，雖知地形，不能得地之利矣。治兵不知九變之術，雖知地利，不能得人之用矣。",
