      "order": 4,
      "canonicalText": "兵非貴益多，惟無武進，足以併力料敵取人而已。夫惟無慮而易敵者，必擒於人。",
      "sentenceIds": [
        "art-of-war_ch-9_p-4_s-1",
        "art-of-war_ch-9_p-4_s-2"
      ],
