        "translation": "軍隊有走、弛、陷、崩、亂、北六種敗象，並非天災地變，而是將領的過失。兵力相當卻以一擊十叫「走」；士卒強悍而軍吏軟弱叫「弛」；軍吏強而士卒弱叫「陷」；部將憤怒不服，遇敵便擅自出戰，主將又不了解其能力，叫「崩」；主將軟弱不嚴、教令不明、官兵職責不定、列陣雜亂，叫「亂」；不能判斷敵情，以少擊眾、以弱擊強，又沒有精銳前鋒，叫「北」。這六種都是失敗原因，是將領的重要責任，不能不察。",
