      "readingAid": {
        "translation": "孫子說：用兵所處的地域形勢，可分為散地、輕地、爭地、交地、衢地、重地、圮地、圍地、死地。諸侯在本國境內作戰，士卒容易眷戀家鄉而離散，叫作散地；進入敵境不深，容易退回，叫作輕地；我方取得有利、敵方取得也有利，叫作爭地；我方可以前往、敵方也可以到來，叫作交地；地接多國，先到便能取得各方援助，叫作衢地；深入敵境，背後已越過許多城邑，叫作重地；山林、險阻、低溼沼澤等難走的地方，叫作圮地；入口狹窄、退路迂遠，敵人能以少擊眾，叫作圍地；迅速奮戰才能生存，不迅速奮戰便會覆亡，叫作死地。因此，在散地不宜交戰，在輕地不可停留，在爭地不宜強攻，在交地不可讓隊伍斷絕，在衢地要結交諸侯，在重地要就地取得足夠補給，在圮地要趕快通過，在圍地要設謀脫困，在死地則必須決戰。",
        "analysis": "本段先按軍隊與本土、敵境、交通和退路的關係，界定九種「地」，再為每一種情勢配上不同處置。這不是單看地貌的地理分類；同一地點會因深入程度、補給線、盟友與敵軍位置不同而改變性質。所謂「重地則掠」，重點是確保遠征軍補給，不能脫離古代戰爭語境解作任意劫掠平民。閱讀時應抓住核心：先判斷部隊所受的離心力、通道與退路，再決定戰、守、行、交或謀，不能把九條口訣機械套用。"
      }
