      "canonicalText": "將軍之事，靜以幽，正以治，能愚士卒之耳目，使之無知。易其事，革其謀，使人無識，易其居，迂其途，使人不得慮。帥與之期，如登高而去其梯，帥與之深，入諸侯之地而發其機。若驅羣羊，驅而往，驅而來，莫知所之。聚三軍之眾，投之於險，此將軍之事也。九地之變，屈伸之利，人情之理，不可不察也。",
