        "translation": "將帥處事，要沉著而深不可測，公正而有條理；能使士卒的耳目不受軍機干擾，不讓他們預先知道。要變更部署、更新計謀，使人無法識破；更換駐地、繞道行進，使人無從推測。將帥授予任務，好比使人登高後抽去梯子；率軍深入諸侯境內，再發動如弩機般不可停止。像驅趕羊群一樣，趕來趕去，羊群並不知道將往何處。集合全軍，把他們置於險境，這是將帥所要處理的事。九種地勢的變化、進退伸屈的利益以及人情心理的規律，都不可不仔細考察。",
