      "id": "art-of-war_ch-11_p-8",
      "chapterId": "art-of-war_ch-11",
      "order": 8,
      "canonicalText": "是故政舉之日，夷關折符，無通其使，厲於廊廟之上，以誅其事，敵人開闔，必亟入之。先其所愛，微與之期，賤墨隨敵，以決戰爭。是故始如處女，敵人開戶，後如脫兔，敵不及拒。",
